using Shop;

public class PriceCalculatorTests
{
    private static Order OrderOf(CustomerType customer) =>
        new(customer, [new OrderLine("A", 100m, 2), new OrderLine("B", 50m, 1)]);

    [Fact]
    public void Regular_customer_pays_the_subtotal() =>
        Assert.Equal(250m, PriceCalculator.Total(OrderOf(CustomerType.Regular)));

    [Fact]
    public void Loyal_customer_gets_five_percent_off() =>
        Assert.Equal(237.50m, PriceCalculator.Total(OrderOf(CustomerType.Loyal)));

    // Q4 promotion (remove end of December).
    [Theory]
    [InlineData(CustomerType.Regular, 1000, 970)]      // 1000 * 0.97
    [InlineData(CustomerType.Loyal, 1000, 921.5)]      // (1000 - 50) * 0.97
    [InlineData(CustomerType.Regular, 999.99, 999.99)] // below threshold
    public void Subtotal_of_1000_or_more_gets_extra_three_percent_off(CustomerType customer, decimal unitPrice, decimal expected) =>
        Assert.Equal(expected, PriceCalculator.Total(new(customer, [new OrderLine("A", unitPrice, 1)])));
}
